import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:mobile_scanner/mobile_scanner.dart';
import 'package:aula_07_recursos_nativos/recurso_service.dart';

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('Android decodifica QR real e o service devolve o texto', (
    tester,
  ) async {
    final pasta = await Directory.systemTemp.createTemp('aula7-qr-');
    final arquivo = File('${pasta.path}/qr.png');
    await arquivo.writeAsBytes(base64Decode(qrPng));
    final scanner = MobileScannerController(autoStart: false);
    try {
      final captura = await scanner.analyzeImage(arquivo.path);
      expect(captura, isNotNull);
      expect(RecursoService().lerQr(captura!), 'UTFPR-AULA-7');
    } finally {
      await scanner.dispose();
      await pasta.delete(recursive: true);
    }
  });
}

// PNG local de demo/qr-utfpr.png, sem dependência de rede ou galeria pessoal.
const qrPng =
    '';
